source='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]

    patterns = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == background:
                c += 1
                continue
            start = c
            while c < w and row[c] != background:
                c += 1
            if c - start > 1:
                patterns.append((c - start, row[start:c]))
    pattern = max(patterns, key=lambda item: item[0])[1]

    markers = []
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == background:
                continue
            neighbors = ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1))
            if all(not (0 <= rr < h and 0 <= cc < w) or grid[rr][cc] == background
                   for rr, cc in neighbors):
                markers.append((r, c))

    output = [row[:] for row in grid]
    for r, c in markers:
        left = c - len(pattern) // 2
        for i, value in enumerate(pattern):
            cc = left + i
            if 0 <= cc < w:
                output[r][cc] = value
    return output
'''
